fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Promote to a wider integer to avoid overflow on multiplications
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    // Basic reachability: must be able to reach the station from either endpoint
    if b < f || b < a - f {
        return -1;
    }
    // For more than one trip, according to spec b must be at least (2*a - f)
    if k > 1 && b < 2 * a - f {
        return -1;
    }
    // If we can just go back and forth k times without ever refueling
    // i.e. require b >= k * a in total range
    if b >= k * a {
        return 0;
    }
    // Otherwise it is feasible, but at least one station refueling is needed
    1
}

